% g.k = 0) AS fsq_g FROM (SELECT x.*, x.dn AS fsp_d, x.msp AS fsp1_n, x.dn * GREATEST(x.np, 1) AS fsp1_d, x.may AS fay_n, x.dn AS fay_d, x.mib AS fib_n, x.dn AS fib_d, x.mne AS fne_n, x.dn AS fne_d, x.man AS fan_n, x.dn AS fan_d, x.man AS fan1_n, x.dn * GREATEST(x.ap, 1) AS fan1_d, x.msd AS fsd_n, x.dn AS fsd_d, x.msd AS fsd1_n, x.dn * GREATEST(x.nsp, 1) AS fsd1_d, x.msi AS fsi_n, x.dn AS fsi_d, x.msi AS fsi1_n, x.dn * GREATEST(x.nsi, 1) AS fsi1_d, x.sisa AS fash_n, x.base AS fash_d, 2 * x.sisa AS fpl_n, x.base * GREATEST(x.tu, 1) AS fpl_d, x.sisa AS fpp_n, x.base * GREATEST(x.tu, 1) AS fpp_d, IF(x.al > 0, x.sisa * IF(x.pgl = 1, 2, 1), x.man) AS fpg_n, IF(x.al > 0, x.base * GREATEST(x.tu, 1), x.dn * GREATEST(x.ap, 1)) AS fpg_d, 2 * x.sisa AS fsl_n, x.base * GREATEST(x.tus, 1) AS fsl_d, x.sisa AS fsq_n, x.base * GREATEST(x.tus, 1) AS fsq_d FROM (SELECT x.*, IF(x.pen IN ('aul', 'radd'), x.sb, x.base) AS dn, IF(x.pen = 'ashabah', x.base - x.sb, 0) AS sisa, 2 * x.al + x.ap AS tu, 2 * x.nsl + x.nsp AS tus, x.msp AS fsp_n FROM (SELECT x.*, CASE WHEN x.ada = 0 THEN 'kosong' WHEN x.fb = 1 THEN 'fb' WHEN x.sb > x.base THEN 'aul' WHEN x.sb = x.base THEN 'exact' WHEN x.ash = 1 THEN 'ashabah' WHEN x.np = 0 AND x.ay = 0 THEN 'radd' ELSE 'fbsisa' END AS pen FROM (SELECT x.*, IF(x.fbk + x.fbn + x.fbs + x.fbp + x.musy > 0, 1, 0) AS fb, IF(x.al > 0 OR x.sash = 1, 1, 0) AS ash FROM (SELECT x.*, IF(x.sash = 1 AND x.sb >= x.base, 1, 0) AS musy FROM (SELECT x.*, x.msp + x.may + x.mib + x.mne + x.man + x.msd + x.msi AS sb FROM (SELECT x.*, x.usp * x.base DIV 24 AS msp, x.uay * x.base DIV 24 AS may, x.uib * x.base DIV 24 AS mib, x.une * x.base DIV 24 AS mne, x.uan * x.base DIV 24 AS man, x.usd * x.base DIV 24 AS msd, x.usi * x.base DIV 24 AS msi FROM (SELECT x.*, IF(x.h8 = 1, IF(x.h3 + x.h6 > 0, 24, 8), IF(x.h4 = 1, IF(x.h3 + x.h6 > 0, 12, 4), IF(x.h6 = 1, 6, IF(x.h3 = 1, IF(x.h2 = 1, 6, 3), IF(x.h2 = 1, 2, 1))))) AS base FROM (SELECT x.*, IF(((x.usp IN (3)) + (x.uay IN (3)) + (x.uib IN (